const root=path.resolve(__dirname,'..'),reportFile=path.join(__dirname,'storage-cleanup-20261102.json');
function walk(p){const s=fs.lstatSync(p);assert(!s.isSymbolicLink(),'Refusing linked path '+p);return s.isDirectory()?fs.readdirSync(p).flatMap(n=>walk(path.join(p,n))):[p]}
function bytes(p){return fs.existsSync(p)?walk(p).reduce((n,f)=>n+fs.statSync(f).size,0):0}
