for(const p of deleteTargets){assert(p.startsWith(root+path.sep));assert(p.startsWith(path.join(root,'exports')+path.sep)||p.startsWith(path.join(root,'design')+path.sep));assert(!p.includes(path.sep+'.git'+path.sep));walk(p)}
const protectedRoots=['app/HotPot/assets/scripts','app/HotPot/assets/resources','app/HotPot/cloudfunctions','design/four-style-previews-20261031','design/fullscreen-menu-review-20261101','design/region-ranking-review-20261101','design/implemented-fullscreen-20261101','design/all-pages-ninepatch-20261030/assets','design/all-pages-ninepatch-20261030/source-art','exports/HotPot-four-style-ui-4mb-20261031','exports/cloudbase-player-dev','exports/cloudbase-regions'];
if(process.argv[2]==='before'){
const protectedFiles={};for(const r of protectedRoots)for(const f of walk(path.join(root,r)))protectedFiles[path.relative(root,f).replaceAll('\\','/')]=hash(f);
const state={date:'2026-11-02',before:sizes(),head:git(['rev-parse','HEAD']),refs:git(['for-each-ref','--format=%(refname) %(objectname)','refs/heads','refs/tags','refs/remotes']),indexHash:hash(path.join(root,'.git/index')),indexEntriesHash:indexEntries(),protectedFiles,deleted:deleteTargets.map(p=>({path:path.relative(root,p).replaceAll('\\','/'),bytes:bytes(p),directory:fs.statSync(p).isDirectory()})),keptAvailableClientBuild:'20261031-four-style-game-ui',sourceClientBuild:'20261101-fullscreen-submenus-ranking',latestSourceBuildNotAvailableLocally:true};
fs.writeFileSync(reportFile,JSON.stringify(state,null,2));console.log(JSON.stringify({before:state.before,plannedDeletedBytes:state.deleted.reduce((n,x)=>n+x.bytes,0),targets:state.deleted.length,protectedFiles:Object.keys(protectedFiles).length},null,2));
}else if(process.argv[2]==='after'){
const state=JSON.parse(fs.readFileSync(reportFile,'utf8'));for(const [f,h]of Object.entries(state.protectedFiles))assert.equal(hash(path.join(root,f)),h,'Protected content changed '+f);assert.equal(git(['rev-parse','HEAD']),state.head);assert.equal(git(['for-each-ref','--format=%(refname) %(objectname)','refs/heads','refs/tags','refs/remotes']),state.refs);assert.equal(indexEntries(),state.indexEntriesHash);for(const d of state.deleted)assert(!fs.existsSync(path.join(root,d.path)),'Obsolete file remains '+d.path);state.after=sizes();state.savedBytes=Object.fromEntries(Object.keys(state.before).map(k=>[k,state.before[k]-state.after[k]]));state.protectedContentUnchanged=true;state.branchHeadsTagsRemotesAndIndexUnchanged=true;state.committed=false;state.pushed=false;fs.writeFileSync(reportFile,JSON.stringify(state,null,2));console.log(JSON.stringify({before:state.before,after:state.after,savedBytes:state.savedBytes,protectedContentUnchanged:true,branchHeadsTagsRemotesAndIndexUnchanged:true},null,2));
}else throw Error('Expected before or after');
